curl -s -g 'http://localhost:16686/jaeger/ui/api/traces?service=product-catalog&operation=oteldemo.ProductCatalogService%2FGetProduct&lookback=2h&limit=40&tags=%7B%22error%22%3A%22true%22%7D' | python3 -c "
import sys,json
d=json.load(sys.stdin)
traces=d.get('data',[])
print('error traces:', len(traces))
seen=set()
for t in traces[:40]:
    for s in t['spans']:
        tags={tg['key']:tg['value'] for tg in s.get('tags',[])}
        if tags.get('error')=='true' or tags.get('otel.status_code')=='ERROR':
            msg=tags.get('app.product.id') or ''
            # collect logs
            for lg in s.get('logs',[]):
                fields={f['key']:f['value'] for f in lg.get('fields',[])}
                m=fields.get('exception.message') or fields.get('message') or fields.get('event')
                if m and m not in seen:
                    seen.add(m); print('LOG:', m, '| productId=', msg)
            st=tags.get('otel.status_description') or tags.get('status.message')
            if st and st not in seen:
                seen.add(st); print('STATUS:', st, '| productId=', msg)
"

